// American Express CSV Parser
// Expected format: Has multiple header rows, data starts after "Date,Date Processed,Description,Amount,..."
// Date format: DD-MMM-YY (e.g., "31-May-25")
// Amount: With dollar sign and commas (e.g., "$33.20")

import { BaseCSVParser } from './BaseCSVParser';
import type { CSVParseResult, ParsedTransaction } from '$lib/models/Transaction';

export class AmexParser extends BaseCSVParser {
	parse(csvContent: string): CSVParseResult {
		const transactions: ParsedTransaction[] = [];
		const errors: string[] = [];

		try {
			csvContent = this.removeBOM(csvContent);
			const rows = this.parseCSV(csvContent);

			if (rows.length < 2) {
				errors.push('CSV file is empty or has no data rows');
				return { transactions, errors };
			}

			// Find the data header row (contains "Date,Date Processed,Description,Amount")
			let headerRowIdx = -1;
			for (let i = 0; i < rows.length; i++) {
				const row = rows[i];
				if (
					row.some((cell) => cell.toLowerCase() === 'date') &&
					row.some((cell) => cell.toLowerCase().includes('description')) &&
					row.some((cell) => cell.toLowerCase() === 'amount')
				) {
					headerRowIdx = i;
					break;
				}
			}

			if (headerRowIdx === -1) {
				errors.push(
					'Invalid American Express CSV format. Could not find header row with Date, Description, and Amount columns'
				);
				return { transactions, errors };
			}

			const header = rows[headerRowIdx];
			const dateIdx = header.findIndex((h) => h.toLowerCase() === 'date');
			const descriptionIdx = header.findIndex((h) => h.toLowerCase() === 'description');
			const amountIdx = header.findIndex((h) => h.toLowerCase() === 'amount');

			if (dateIdx === -1 || descriptionIdx === -1 || amountIdx === -1) {
				errors.push('Could not find required columns in header row');
				return { transactions, errors };
			}

			// Parse data rows (start after header)
			for (let i = headerRowIdx + 1; i < rows.length; i++) {
				const row = rows[i];
				if (row.length < 3) continue; // Skip incomplete rows

				const dateStr = row[dateIdx]?.trim();
				const description = row[descriptionIdx]?.trim();
				const amountStr = row[amountIdx]?.trim();

				// Skip empty rows
