// CSV Parser Factory
// Automatically selects and returns the appropriate parser based on credit card type or CSV format

import type { CreditCardType } from '$lib/models/Transaction';
import type { ICSVParser } from './BaseCSVParser';
import { PCFinancialParser } from './PCFinancialParser';
import { AmexParser } from './AmexParser';
import { RBCFinancialParser } from './RBCFinancialParser';
import { TDBankParser } from './TDBankParser';
import { SimpliiFinancialParser } from './SimpliiFinancialParser';
import { EQBankParser } from './EQBankParser';
import { WealthSimpleParser } from './WealthSimpleParser'; // #{#wsp3b}

export class CSVParserFactory {
	/**
	 * Get a parser for a specific credit card type
	 */
	static getParser(creditCardType: CreditCardType): ICSVParser {
		switch (creditCardType) {
			case 'PC Financial':
				return new PCFinancialParser();
			case 'American Express':
				return new AmexParser();
			case 'RBC Financial':
				return new RBCFinancialParser();
			case 'TD Bank':
				return new TDBankParser();
			case 'Simplii Financial':
				return new SimpliiFinancialParser();
			case 'EQ Bank':
				return new EQBankParser();
			case 'Wealth Simple': // #{#wsp3b}
				return new WealthSimpleParser();
			default:
				throw new Error(`Unsupported credit card type: ${creditCardType}`);
		}
	}

	/**
	 * Auto-detect the appropriate parser based on CSV content
	 * Returns the parser and credit card type, or null if no match
	 */
	static detectParser(csvContent: string): {
		parser: ICSVParser;
		creditCardType: CreditCardType;
	} | null {
		// Order matters! Check more specific formats first before generic ones
		// TD Bank has no header, so it needs to be checked last
		const parsers: Array<{ parser: ICSVParser; type: CreditCardType }> = [
			{ parser: new AmexParser(), type: 'American Express' },
			{ parser: new PCFinancialParser(), type: 'PC Financial' },
			{ parser: new RBCFinancialParser(), type: 'RBC Financial' },
			{ parser: new SimpliiFinancialParser(), type: 'Simplii Financial' },
			{ parser: new EQBankParser(), type: 'EQ Bank' },
			{ parser: new WealthSimpleParser(), type: 'Wealth Simple' }, // #{#wsp3b}
			{ parser: new TDBankParser(), type: 'TD Bank' } // Last - has no header, most generic
		];

		// Try each parser's validation method
		for (const { parser, type } of parsers) {
			if (parser.validateFormat(csvContent)) {
				return { parser, creditCardType: type };
			}
		}

		return null;
	}

	/**
	 * Get all available parsers
	 */
	static getAllParsers(): Array<{ parser: ICSVParser; type: CreditCardType }> {
		return [
			{ parser: new PCFinancialParser(), type: 'PC Financial' },
			{ parser: new AmexParser(), type: 'American Express' },
			{ parser: new RBCFinancialParser(), type: 'RBC Financial' },
			{ parser: new TDBankParser(), type: 'TD Bank' },
			{ parser: new SimpliiFinancialParser(), type: 'Simplii Financial' },
			{ parser: new EQBankParser(), type: 'EQ Bank' },
			{ parser: new WealthSimpleParser(), type: 'Wealth Simple' } // #{#wsp3b}
		];
	}
}

