import { describe, it, expect } from 'vitest';
import { BaseCSVParser } from '../BaseCSVParser';
import type { CSVParseResult } from '$lib/models/Transaction';

// Test implementation of BaseCSVParser for testing protected methods
class TestCSVParser extends BaseCSVParser {
	parse(): CSVParseResult {
		return { transactions: [], errors: [] };
	}

	validateFormat(): boolean {
		return true;
	}

	// Expose protected methods for testing
	public testNormalizeAmount(amount: number | null, invertSign: boolean = true): number | null {
		return this.normalizeAmount(amount, invertSign);
	}
}

describe('BaseCSVParser', () => {
	const parser = new TestCSVParser();

	describe('normalizeAmount - #{#trn1b}', () => {
		describe('when invertSign is true (for banks like Amex where positive = expense in CSV)', () => {
			it('should convert positive expense to negative', () => {
				// American Express: 50.00 (expense in CSV) → -50.00 (negative = expense)
				expect(parser.testNormalizeAmount(-50.0, true)).toBe(50.0);
			});

			it('should convert negative refund to positive', () => {
				// American Express: -25.00 (refund in CSV) → 25.00 (positive = refund)
				expect(parser.testNormalizeAmount(25.0, true)).toBe(-25.0);
			});

			it('should handle large negative amounts', () => {
				expect(parser.testNormalizeAmount(-1234.56, true)).toBe(1234.56);
			});

			it('should handle large positive amounts', () => {
				expect(parser.testNormalizeAmount(9999.99, true)).toBe(-9999.99);
			});

			it('should handle amounts with many decimals', () => {
				expect(parser.testNormalizeAmount(-123.456789, true)).toBe(123.456789);
			});
		});

		describe('when invertSign is false (for banks already using negative for expenses)', () => {
			it('should keep negative expense as negative', () => {
				// PC Financial: -50.00 (expense) → -50.00 (negative = expense)
				expect(parser.testNormalizeAmount(50.0, false)).toBe(50.0);
			});

			it('should keep positive refund as positive', () => {
				// PC Financial: 25.00 (refund) → 25.00 (positive = refund)
				expect(parser.testNormalizeAmount(-25.0, false)).toBe(-25.0);
			});

			it('should handle large amounts unchanged', () => {
				expect(parser.testNormalizeAmount(5000.0, false)).toBe(5000.0);
				expect(parser.testNormalizeAmount(-5000.0, false)).toBe(-5000.0);
			});
		});

		describe('edge cases', () => {
			it('should handle null amount', () => {
				expect(parser.testNormalizeAmount(null, true)).toBeNull();
				expect(parser.testNormalizeAmount(null, false)).toBeNull();
			});

			it('should handle zero amount with invertSign true', () => {
				expect(parser.testNormalizeAmount(0, true)).toBe(0);
			});

			it('should handle zero amount with invertSign false', () => {
				expect(parser.testNormalizeAmount(0, false)).toBe(0);
			});

			it('should handle negative zero', () => {
				expect(parser.testNormalizeAmount(-0, true)).toBe(0);
				expect(parser.testNormalizeAmount(-0, false)).toBe(0);
			});

			it('should handle very small amounts', () => {
				expect(parser.testNormalizeAmount(-0.01, true)).toBe(0.01);
				expect(parser.testNormalizeAmount(0.01, true)).toBe(-0.01);
			});

			it('should handle very large amounts', () => {
				expect(parser.testNormalizeAmount(-999999.99, true)).toBe(999999.99);
				expect(parser.testNormalizeAmount(999999.99, false)).toBe(999999.99);
			});
		});

		describe('default parameter behavior', () => {
			it('should default invertSign to true when not specified', () => {
				// Default should invert sign
				expect(parser.testNormalizeAmount(-50.0)).toBe(50.0);
				expect(parser.testNormalizeAmount(25.0)).toBe(-25.0);
			});
		});
	});
});

