			const csv = header + '"2025-01-15","2025-01-16","","NO TYPE","40.00","CAD"';
			const result = parser.parse(csv);

			expect(result.transactions).toHaveLength(1);
			expect(result.transactions[0].amount).toBe(40.0);
		});

		it('should match the type value case-insensitively', () => {
			// txnType is lower-cased before comparison, so "PURCHASE" is still negated.
			const csv = header + '"2025-01-15","2025-01-16","PURCHASE","SHOUTING","25.00","CAD"';
			const result = parser.parse(csv);

			expect(result.transactions).toHaveLength(1);
			expect(result.transactions[0].amount).toBe(-25.0);
		});

		it('should treat refund-variant types as positive credits regardless of CSV sign', () => {
			const csv =
				header +
				'"2025-01-15","2025-01-16","Refund initiated","REFUND A","-10.00","CAD"\n' +
				'"2025-01-15","2025-01-16","Refund settled","REFUND B","-20.00","CAD"';
			const result = parser.parse(csv);

			expect(result.transactions).toHaveLength(2);
			expect(result.transactions[0].amount).toBe(10.0);
			expect(result.transactions[1].amount).toBe(20.0);
		});
	});
});

