/**
 * Tests for Receipts View with Shared Date Filter
 *
 * Specifications covered:
 * - #{#sdf1a} URL Query Parameter Date Filters
 * - #{#sdf1b} Automatic Filter Application from URL
 * - #{#sdf2a} Receipts View URL Integration
 * - #{#sdf5a} URL Parameter Validation
 */

import { describe, it, expect } from 'vitest';
import { getValidDate } from '$lib/utils/dateValidation';

describe('#{#sdf5a} URL Parameter Validation - getValidDate()', () => {
	it('should return empty string for null input', () => {
		expect(getValidDate(null)).toBe('');
	});

	it('should return empty string for empty string input', () => {
		expect(getValidDate('')).toBe('');
	});

	it('should accept valid date in YYYY-MM-DD format', () => {
		expect(getValidDate('2025-01-15')).toBe('2025-01-15');
	});

	it('should accept leap year dates', () => {
		expect(getValidDate('2024-02-29')).toBe('2024-02-29');
	});

	it('should reject invalid date format (MM/DD/YYYY)', () => {
		expect(getValidDate('01/15/2025')).toBe('');
	});

	it('should reject invalid date format (DD-MM-YYYY)', () => {
		expect(getValidDate('15-01-2025')).toBe('');
	});

	it('should reject invalid month (13)', () => {
		expect(getValidDate('2025-13-01')).toBe('');
	});

	it('should reject invalid day (32)', () => {
		expect(getValidDate('2025-01-32')).toBe('');
	});

	it('should reject non-leap year Feb 29', () => {
		expect(getValidDate('2025-02-29')).toBe('');
	});

	it('should reject invalid day for month (April 31)', () => {
		expect(getValidDate('2025-04-31')).toBe('');
	});

	it('should reject XSS attempts', () => {
		expect(getValidDate('<script>alert("xss")</script>')).toBe('');
	});

	it('should reject SQL injection attempts', () => {
		expect(getValidDate("'; DROP TABLE receipts; --")).toBe('');
	});

	it('should reject dates with extra characters', () => {
		expect(getValidDate('2025-01-15 extra')).toBe('');
	});

	it('should reject dates with time component', () => {
		expect(getValidDate('2025-01-15T10:30:00')).toBe('');
	});

	it('should reject partial dates', () => {
		expect(getValidDate('2025-01')).toBe('');
		expect(getValidDate('2025')).toBe('');
	});
});

describe('#{#sdf1a} URL Query Parameter Date Filters - URLSearchParams behavior', () => {
	it('should read dateFrom from URL query parameters', () => {
		const params = new URLSearchParams('dateFrom=2025-01-01');
		expect(params.get('dateFrom')).toBe('2025-01-01');
	});

	it('should read dateTo from URL query parameters', () => {
		const params = new URLSearchParams('dateTo=2025-01-31');
		expect(params.get('dateTo')).toBe('2025-01-31');
	});

	it('should read both dateFrom and dateTo from URL', () => {
		const params = new URLSearchParams('dateFrom=2025-01-01&dateTo=2025-01-31');
		expect(params.get('dateFrom')).toBe('2025-01-01');
		expect(params.get('dateTo')).toBe('2025-01-31');
	});

	it('should handle missing dateFrom parameter', () => {
		const params = new URLSearchParams('dateTo=2025-01-31');
		expect(params.get('dateFrom')).toBeNull();
		expect(params.get('dateTo')).toBe('2025-01-31');
	});

	it('should handle missing dateTo parameter', () => {
		const params = new URLSearchParams('dateFrom=2025-01-01');
		expect(params.get('dateFrom')).toBe('2025-01-01');
		expect(params.get('dateTo')).toBeNull();
	});

	it('should handle empty query parameters', () => {
		const params = new URLSearchParams('');
		expect(params.get('dateFrom')).toBeNull();
		expect(params.get('dateTo')).toBeNull();
	});

	it('should handle empty parameter values', () => {
		const params = new URLSearchParams('dateFrom=&dateTo=');
		expect(params.get('dateFrom')).toBe('');
		expect(params.get('dateTo')).toBe('');
