		params.set('dateFrom', dateFrom);

		expect(params.get('existingParam')).toBe('value');
		expect(params.get('dateFrom')).toBe('2025-01-01');
		expect(params.toString()).toContain('existingParam=value');
		expect(params.toString()).toContain('dateFrom=2025-01-01');
