/**
 * Receipt Date Validation Utility
 *
 * #{#dtv1a authority=platform} - Suspicious Date Detection
 *
 * Detects receipt dates that are suspiciously old (>42 days) or in the future,
 * which likely indicate OCR misclassification.
 *
 * @module dateValidation
 */

const SIX_WEEKS_DAYS = 42;
const MS_PER_DAY = 1000 * 60 * 60 * 24;

/**
 * Determines if a receipt transaction date is suspicious (likely OCR error)
 *
 * A date is considered suspicious if:
 * - More than 42 days (6 weeks) in the past
 * - In the future
 *
 * @param transactionDate - ISO date string (YYYY-MM-DD) or null
 * @returns true if date is suspicious, false otherwise
 *
 * @example
 * isSuspiciousDate('2025-12-09') // false (today)
 * isSuspiciousDate('2025-09-01') // true (>6 weeks old)
 * isSuspiciousDate('2026-01-01') // true (future)
 * isSuspiciousDate(null) // false (gracefully handled)
 */
export function isSuspiciousDate(transactionDate: string | null | undefined): boolean {
	// Gracefully handle missing/invalid dates
	if (!transactionDate || transactionDate === '') {
		return false;
	}

	// Parse date and handle invalid formats
	const receiptDate = new Date(transactionDate);

	// Check if date is invalid (NaN)
	if (isNaN(receiptDate.getTime())) {
		return false; // Invalid date format, not suspicious, just malformed
	}

	const today = new Date();

	// Remove time component for accurate day comparison (use UTC to avoid timezone issues)
	receiptDate.setUTCHours(0, 0, 0, 0);
	today.setUTCHours(0, 0, 0, 0);

	// Calculate difference in milliseconds, then convert to days
	const diffMs = today.getTime() - receiptDate.getTime();
	const diffDays = Math.floor(diffMs / MS_PER_DAY);

	// Flag if more than 6 weeks old OR in the future
	return diffDays > SIX_WEEKS_DAYS || diffDays < 0;
}

/**
 * Calculates the age of a receipt date in calendar days
 *
 * Positive values indicate past dates, negative values indicate future dates.
 *
 * @param transactionDate - ISO date string (YYYY-MM-DD)
 * @returns Number of days between transaction date and today (negative if future)
 *
 * @example
 * calculateDateAge('2025-12-09') // 0 (today)
 * calculateDateAge('2025-12-08') // 1 (yesterday)
 * calculateDateAge('2025-12-10') // -1 (tomorrow)
 */
export function calculateDateAge(transactionDate: string): number {
	const receiptDate = new Date(transactionDate);
	const today = new Date();

	// Remove time component for accurate day comparison (use UTC to avoid timezone issues)
	receiptDate.setUTCHours(0, 0, 0, 0);
	today.setUTCHours(0, 0, 0, 0);

	const diffMs = today.getTime() - receiptDate.getTime();
	return Math.floor(diffMs / MS_PER_DAY);
}

/**
 * Validates and returns a date string in YYYY-MM-DD format
 * Returns empty string if the date is invalid
 *
 * Used for validating URL query parameters for date filters
 */
export function getValidDate(dateString: string | null): string {
	if (!dateString) return '';

	// Check format: YYYY-MM-DD
	const dateRegex = /^\d{4}-\d{2}-\d{2}$/;
	if (!dateRegex.test(dateString)) return '';

	// Validate that the date is actually valid
	const date = new Date(dateString);
	if (isNaN(date.getTime())) return '';

	// Verify the string matches the parsed date (catches invalid dates like 2023-02-30)
	const [year, month, day] = dateString.split('-').map(Number);
	if (
		date.getUTCFullYear() !== year ||
		date.getUTCMonth() !== month - 1 ||
		date.getUTCDate() !== day
	) {
		return '';
	}

	return dateString;
}

