/**
 * Characterization tests for the shared date-filter module (RF-02).
 *
 * These lock the date-filter glue that is currently copy-pasted across the four
 * list pages — `expenses`, `receipts`, `transactions`, `reconciliation` — BEFORE
 * it is extracted into `$lib/utils/sharedDateFilter`. They are written against the
 * module's contract, not against inline reimplementations, so they actually bind
 * to the extracted unit (unlike the previous version of this file, which tested
 * private copies of the logic and gave false confidence).
 *
 * Repo convention (see the other *-page-filters specs): pure logic is unit-tested
 * in the node project; the reactive/`goto` wiring on each page is covered by
 * Playwright e2e. This file therefore targets the pure, extractable functions the
 * shared composable will delegate to.
 *
 * Specifications covered:
 * - #{#sdf1a} URL Query Parameter Date Filters
 * - #{#sdf1b} Automatic Filter Application from URL (client-side predicate)
 * - #{#sdf2a} URL Update Logic (apply / clear)
 * - #{#sdf5a} URL Parameter Validation
 *
 * RED PHASE: `$lib/utils/sharedDateFilter` does not exist yet — every test here
 * fails at import until RF-02 creates the module. That is intentional: it is the
 * red safety net that drives the extraction.
 */

import { describe, it, expect } from 'vitest';
import {
	readDateFilter,
	hasActiveDateFilter,
	matchesDateRange,
	applyDateFilterParams,
	clearDateFilterParams,
	toExclusiveEndBoundary,
	defaultMonthStart,
	defaultMonthEnd
} from '$lib/utils/sharedDateFilter';

describe('#{#sdf1a}/#{#sdf5a} readDateFilter - read + validate from URL', () => {
	it('reads both dateFrom and dateTo when present and valid', () => {
		const params = new URLSearchParams('dateFrom=2025-01-01&dateTo=2025-01-31');
		expect(readDateFilter(params)).toEqual({ dateFrom: '2025-01-01', dateTo: '2025-01-31' });
	});

	it('reads dateFrom only, leaving dateTo empty', () => {
		const params = new URLSearchParams('dateFrom=2025-01-01');
		expect(readDateFilter(params)).toEqual({ dateFrom: '2025-01-01', dateTo: '' });
	});

	it('reads dateTo only, leaving dateFrom empty', () => {
		const params = new URLSearchParams('dateTo=2025-01-31');
		expect(readDateFilter(params)).toEqual({ dateFrom: '', dateTo: '2025-01-31' });
	});

	it('returns empty strings when neither parameter is present', () => {
		expect(readDateFilter(new URLSearchParams(''))).toEqual({ dateFrom: '', dateTo: '' });
	});

	it('treats empty parameter values as no filter', () => {
		const params = new URLSearchParams('dateFrom=&dateTo=');
		expect(readDateFilter(params)).toEqual({ dateFrom: '', dateTo: '' });
	});

	it('accepts a leap-year date', () => {
		const params = new URLSearchParams('dateFrom=2024-02-29');
		expect(readDateFilter(params).dateFrom).toBe('2024-02-29');
	});

	it('rejects a wrong format (MM/DD/YYYY) as empty', () => {
		const params = new URLSearchParams('dateFrom=01/15/2025');
		expect(readDateFilter(params).dateFrom).toBe('');
	});

	it('rejects an impossible calendar date (Feb 29 in a non-leap year)', () => {
		const params = new URLSearchParams('dateFrom=2025-02-29');
		expect(readDateFilter(params).dateFrom).toBe('');
	});

	it('rejects a date with a trailing time component', () => {
		const params = new URLSearchParams('dateTo=2025-01-15T10:30:00');
		expect(readDateFilter(params).dateTo).toBe('');
	});

	it('rejects XSS/SQL-injection payloads as empty', () => {
		const xss = new URLSearchParams();
		xss.set('dateFrom', '<script>alert("xss")</script>');
		xss.set('dateTo', "'; DROP TABLE receipts; --");
		expect(readDateFilter(xss)).toEqual({ dateFrom: '', dateTo: '' });
	});
});

describe('#{#sdf1a} hasActiveDateFilter', () => {
	it('is false when both bounds are empty', () => {
		expect(hasActiveDateFilter('', '')).toBe(false);
	});

	it('is true when only dateFrom is set', () => {
		expect(hasActiveDateFilter('2025-01-01', '')).toBe(true);
	});

	it('is true when only dateTo is set', () => {
		expect(hasActiveDateFilter('', '2025-01-31')).toBe(true);
	});

	it('is true when both bounds are set', () => {
		expect(hasActiveDateFilter('2025-01-01', '2025-01-31')).toBe(true);
	});
});

describe('#{#sdf1b} matchesDateRange - client-side in-memory predicate', () => {
	// This single predicate must reproduce the behaviour of all four pages. Three
	// pages (expenses/receipts/reconciliation) guard a nullable date and KEEP rows
	// with no date; transactions has a non-null date column, so the guarded and
	// unguarded variants behave identically for it. The predicate below preserves
	// both: a missing date is always kept.

	describe('rows with no date are always kept', () => {
		it('keeps a null date even when both bounds are set', () => {
			expect(matchesDateRange(null, '2025-01-01', '2025-01-31')).toBe(true);
		});

		it('keeps an undefined date even when both bounds are set', () => {
			expect(matchesDateRange(undefined, '2025-01-01', '2025-01-31')).toBe(true);
		});

		it('keeps an empty-string date even when both bounds are set', () => {
			expect(matchesDateRange('', '2025-01-01', '2025-01-31')).toBe(true);
		});
	});

	describe('no active filter', () => {
		it('keeps any dated row when both bounds are empty', () => {
			expect(matchesDateRange('2025-06-15', '', '')).toBe(true);
		});

		it('keeps a null-dated row when both bounds are empty', () => {
			expect(matchesDateRange(null, '', '')).toBe(true);
		});
	});

	describe('dateFrom only (lower bound, inclusive)', () => {
		it('keeps a date after the lower bound', () => {
			expect(matchesDateRange('2025-02-10', '2025-02-01', '')).toBe(true);
		});

		it('keeps a date exactly on the lower bound', () => {
			expect(matchesDateRange('2025-02-01', '2025-02-01', '')).toBe(true);
		});

		it('excludes a date before the lower bound', () => {
			expect(matchesDateRange('2025-01-31', '2025-02-01', '')).toBe(false);
		});
	});

	describe('dateTo only (upper bound, inclusive)', () => {
		it('keeps a date before the upper bound', () => {
			expect(matchesDateRange('2025-01-10', '', '2025-01-31')).toBe(true);
		});

		it('keeps a date exactly on the upper bound', () => {
			expect(matchesDateRange('2025-01-31', '', '2025-01-31')).toBe(true);
		});

		it('excludes a date after the upper bound', () => {
			expect(matchesDateRange('2025-02-01', '', '2025-01-31')).toBe(false);
		});
	});

	describe('full range (both bounds, inclusive)', () => {
		it('keeps a date inside the range', () => {
			expect(matchesDateRange('2025-01-15', '2025-01-01', '2025-01-31')).toBe(true);
		});

		it('keeps a date on the lower boundary', () => {
			expect(matchesDateRange('2025-01-01', '2025-01-01', '2025-01-31')).toBe(true);
		});

		it('keeps a date on the upper boundary', () => {
			expect(matchesDateRange('2025-01-31', '2025-01-01', '2025-01-31')).toBe(true);
		});

		it('excludes a date below the range', () => {
			expect(matchesDateRange('2024-12-31', '2025-01-01', '2025-01-31')).toBe(false);
		});

		it('excludes a date above the range', () => {
			expect(matchesDateRange('2025-02-01', '2025-01-01', '2025-01-31')).toBe(false);
		});
	});

	it('compares ISO strings lexicographically across year boundaries', () => {
		// Guards against a regression to Date-based parsing (banned by CLAUDE.md for
		// date-only strings): plain YYYY-MM-DD string comparison must order correctly.
		expect(matchesDateRange('2024-12-31', '2025-01-01', '')).toBe(false);
		expect(matchesDateRange('2025-01-01', '2025-01-01', '')).toBe(true);
	});
});

describe('#{#sdf2a} applyDateFilterParams - build URL params for "Apply"', () => {
	it('sets both date params from an empty query', () => {
		const result = applyDateFilterParams(new URLSearchParams(''), '2025-01-01', '2025-01-31');
		expect(result.toString()).toBe('dateFrom=2025-01-01&dateTo=2025-01-31');
	});

	it('sets dateFrom and removes dateTo when dateTo is empty', () => {
		const result = applyDateFilterParams(new URLSearchParams(''), '2025-01-01', '');
		expect(result.get('dateFrom')).toBe('2025-01-01');
		expect(result.has('dateTo')).toBe(false);
	});

	it('sets dateTo and removes dateFrom when dateFrom is empty', () => {
		const result = applyDateFilterParams(new URLSearchParams(''), '', '2025-01-31');
		expect(result.get('dateTo')).toBe('2025-01-31');
		expect(result.has('dateFrom')).toBe(false);
	});

	it('removes both date params when both bounds are empty', () => {
		const result = applyDateFilterParams(
			new URLSearchParams('dateFrom=2025-01-01&dateTo=2025-01-31'),
			'',
			''
		);
		expect(result.has('dateFrom')).toBe(false);
		expect(result.has('dateTo')).toBe(false);
	});

	it('preserves unrelated query parameters', () => {
		const result = applyDateFilterParams(
			new URLSearchParams('category=groceries&page=2'),
			'2025-01-01',
			'2025-01-31'
		);
		expect(result.get('category')).toBe('groceries');
		expect(result.get('page')).toBe('2');
		expect(result.get('dateFrom')).toBe('2025-01-01');
		expect(result.get('dateTo')).toBe('2025-01-31');
	});

	it('overwrites pre-existing date params with the new values', () => {
		const result = applyDateFilterParams(
			new URLSearchParams('dateFrom=2024-01-01&dateTo=2024-12-31&category=fuel'),
			'2025-06-01',
			''
		);
		expect(result.get('dateFrom')).toBe('2025-06-01');
		expect(result.has('dateTo')).toBe(false);
		expect(result.get('category')).toBe('fuel');
	});

	it('does not mutate the input params', () => {
		const input = new URLSearchParams('category=fuel');
		applyDateFilterParams(input, '2025-01-01', '2025-01-31');
		expect(input.toString()).toBe('category=fuel');
	});
});

describe('#{#sdf2a} clearDateFilterParams - build URL params for "Clear"', () => {
	it('removes both date params', () => {
