/**
 * TEMPORARY validation harness (delete after RF-02 lands).
 *
 * Purpose: prove that the expected values asserted in `sharedDateFilter.spec.ts`
 * actually match what the four list pages do TODAY — before the shared module
 * exists. Each oracle below is lifted VERBATIM from the current page source (file
 * + line noted) and fed the exact inputs used in the real spec. If these pass,
 * the real spec's hand-authored expectations are a faithful characterization of
 * current behaviour, not a guess.
 *
 * The two intentionally-changed helpers (defaultMonth*, timezone safety) are
 * checked separately and their divergence from current code is asserted explicitly.
 */

import { describe, it, expect } from 'vitest';
import { getValidDate } from '$lib/utils/dateValidation';

// ── Oracles copied verbatim from the current pages ────────────────────────────

// readDateFilter oracle — expenses/+page.svelte:74-75 (identical on all 4 pages):
//   let urlDateFrom = $derived(getValidDate($page.url.searchParams.get('dateFrom')));
function oracleRead(params: URLSearchParams) {
	return {
		dateFrom: getValidDate(params.get('dateFrom')),
		dateTo: getValidDate(params.get('dateTo'))
	};
}

// matchesDateRange oracle A — receipts/+page.svelte:315-316 (also expenses:366-369,
// reconciliation:189-190): nullable date, guarded.
function oracleGuardedPredicate(date: string | null | undefined, from: string, to: string): boolean {
	if (from && date && date < from) return false;
	if (to && date && date > to) return false;
	return true;
}

// matchesDateRange oracle B — transactions/+page.svelte:236-237: non-null column,
// UNguarded. Included to prove the consolidated predicate is equivalent for
// transactions (whose date is never null).
function oracleTxnPredicate(date: string, from: string, to: string): boolean {
	if (from && date < from) return false;
	if (to && date > to) return false;
	return true;
}

// applyDateFilterParams oracle — expenses/+page.svelte:474-490 (identical shape on
// all 4 pages): copy current params, set-when-truthy / delete-when-empty.
function oracleApply(current: URLSearchParams, from: string, to: string): URLSearchParams {
	const params = new URLSearchParams(current);
	if (from) params.set('dateFrom', from);
	else params.delete('dateFrom');
	if (to) params.set('dateTo', to);
	else params.delete('dateTo');
	return params;
}

// clearDateFilterParams oracle — expenses/+page.svelte:496-501.
function oracleClear(current: URLSearchParams): URLSearchParams {
	const params = new URLSearchParams(current);
	params.delete('dateFrom');
	params.delete('dateTo');
	return params;
}

// hasActiveDateFilter oracle — the date portion of each page's hasActiveFilters.
function oracleHasActive(from: string, to: string): boolean {
	return !!(from || to);
}

// toExclusiveEndBoundary oracle — transactions/+page.svelte:178-181, verbatim.
function oracleExclusiveEnd(to: string): string {
	const toDateObj = new Date(to + 'T12:00:00');
	toDateObj.setDate(toDateObj.getDate() + 1);
	return toDateObj.toISOString().split('T')[0];
}

// ── Validate the real spec's expectations against those oracles ───────────────

describe('ORACLE: readDateFilter expectations match getValidDate (real) on real pages', () => {
	it('valid pair', () => {
		expect(oracleRead(new URLSearchParams('dateFrom=2025-01-01&dateTo=2025-01-31'))).toEqual({
			dateFrom: '2025-01-01',
			dateTo: '2025-01-31'
		});
	});
	it('leap-year date passes', () => {
		expect(oracleRead(new URLSearchParams('dateFrom=2024-02-29')).dateFrom).toBe('2024-02-29');
	});
	it('wrong format rejected', () => {
		expect(oracleRead(new URLSearchParams('dateFrom=01/15/2025')).dateFrom).toBe('');
	});
	it('impossible date rejected', () => {
		expect(oracleRead(new URLSearchParams('dateFrom=2025-02-29')).dateFrom).toBe('');
	});
	it('time component rejected', () => {
		expect(oracleRead(new URLSearchParams('dateTo=2025-01-15T10:30:00')).dateTo).toBe('');
	});
	it('XSS/SQLi rejected', () => {
		const p = new URLSearchParams();
		p.set('dateFrom', '<script>alert("xss")</script>');
		p.set('dateTo', "'; DROP TABLE receipts; --");
		expect(oracleRead(p)).toEqual({ dateFrom: '', dateTo: '' });
	});
});

describe('ORACLE: matchesDateRange expectations match both current page predicates', () => {
	// (input, from, to, expected) — mirrors the real spec's matchesDateRange cases.
	const cases: Array<[string | null | undefined, string, string, boolean]> = [
		[null, '2025-01-01', '2025-01-31', true],
		[undefined, '2025-01-01', '2025-01-31', true],
		['', '2025-01-01', '2025-01-31', true],
		['2025-06-15', '', '', true],
		[null, '', '', true],
		['2025-02-10', '2025-02-01', '', true],
		['2025-02-01', '2025-02-01', '', true],
		['2025-01-31', '2025-02-01', '', false],
		['2025-01-10', '', '2025-01-31', true],
		['2025-01-31', '', '2025-01-31', true],
		['2025-02-01', '', '2025-01-31', false],
		['2025-01-15', '2025-01-01', '2025-01-31', true],
		['2025-01-01', '2025-01-01', '2025-01-31', true],
		['2025-01-31', '2025-01-01', '2025-01-31', true],
		['2024-12-31', '2025-01-01', '2025-01-31', false],
		['2025-02-01', '2025-01-01', '2025-01-31', false]
	];

	it('guarded predicate (expenses/receipts/reconciliation) yields the asserted values', () => {
		for (const [date, from, to, expected] of cases) {
			expect(oracleGuardedPredicate(date, from, to), `date=${date} from=${from} to=${to}`).toBe(
				expected
			);
		}
	});

	it('transactions (non-null) predicate agrees for every non-null case', () => {
		for (const [date, from, to, expected] of cases) {
			if (date == null || date === '') continue; // transactions column is never null
			expect(oracleTxnPredicate(date, from, to), `date=${date} from=${from} to=${to}`).toBe(
				expected
			);
		}
	});
});

describe('ORACLE: applyDateFilterParams expectations match current page code', () => {
	it('both set from empty', () => {
		expect(oracleApply(new URLSearchParams(''), '2025-01-01', '2025-01-31').toString()).toBe(
			'dateFrom=2025-01-01&dateTo=2025-01-31'
		);
	});
	it('from set, to deleted', () => {
