function getAmountClass(amount: number): string {
	return amount < 0 ? 'text-red-600' : 'text-green-600';
}

function applyClientFilters(txns: TransactionRow[]): TransactionRow[] {
	return txns.filter((t) => {
		// #{#sdf1b} Filter by date range using URL parameters
		if (urlDateFrom && t.transaction_date < urlDateFrom) return false;
		if (urlDateTo && t.transaction_date > urlDateTo) return false;

		// Filter by vendor name (local state)
		if (filterVendor) {
			const vendorSearch = filterVendor.toLowerCase();
			const vendor = t.vendor_name.toLowerCase();
			if (!vendor.includes(vendorSearch)) return false;
		}

		// Filter by amount range (local state)
		if (filterAmountMin) {
			const minAmount = parseFloat(filterAmountMin);
			if (!isNaN(minAmount) && Math.abs(t.amount) < minAmount) return false;
		}
		if (filterAmountMax) {
			const maxAmount = parseFloat(filterAmountMax);
			if (!isNaN(maxAmount) && Math.abs(t.amount) > maxAmount) return false;
		}

		// #{#tcf1a} Filter by credit/bank type (local state)
		if (filterCreditCardType !== 'all') {
			if (t.credit_card_type !== filterCreditCardType) return false;
		}

		return true;
	});
}

function applyFilterValues(): void {
	// #{#sdf2c} Update URL with date filters
	const params = new URLSearchParams($page.url.searchParams);

	if (tempFilterDateFrom) params.set('dateFrom', tempFilterDateFrom);
	else params.delete('dateFrom');

	if (tempFilterDateTo) params.set('dateTo', tempFilterDateTo);
	else params.delete('dateTo');

	goto(`${$page.url.pathname}?${params.toString()}`, { replaceState: true, keepFocus: true });

	// Apply non-date filters locally
	filterVendor = tempFilterVendor;
	filterAmountMin = tempFilterAmountMin;
	filterAmountMax = tempFilterAmountMax;
	filterCreditCardType = tempFilterCreditCardType; // #{#tcf1a}
}

function clearClientFilters(): void {
	// #{#sdf2c} Clear URL date filters
	const params = new URLSearchParams($page.url.searchParams);
	params.delete('dateFrom');
	params.delete('dateTo');
	goto(`${$page.url.pathname}?${params.toString()}`, { replaceState: true, keepFocus: true });

